const fs = require('node:fs');
const path = require('node:path');
const records = JSON.parse(fs.readFileSync(path.join(__dirname,'raw-records.json'),'utf8'));
const DOC='https://docs.ruby-lang.org/en/3.4/';
const find = key => {const r=records.find(r=>r._key===key);if(!r)throw Error(key);return r;};
function set(key,answer,explanation,example='',points=[],issues=[]){Object.assign(find(key),{directAnswer:answer,explanation,example,importantPoints:points,issues:[...find(key).issues,...issues]});}
function topic(re,answer,explanation,example='',points=[],category='A',difficulty='Intermediate'){
 for(const r of records){if(re.test(r.question)){Object.assign(r,{directAnswer:answer,explanation,example,importantPoints:[...r.importantPoints,...points],category,difficulty});}}
}
for(const r of records){
 let s=r.sourceAnswer.replace(/^Answer:\s*/,'').replace(/^(?:Ans-|Ans-The|Answer\s*[–-]|Answer-\s*|Answer\s*:\s*)/,'').trim();
 let paragraphs=s.split(/\n\s*\n/).filter(p=>p.trim());
 let first=paragraphs.find(p=>!/^This is one of|^These are |^It is one of|^Here are |^See also|^You may |^You can also expect/.test(p));
 r.directAnswer=(first||'The supplied source contains the prompt but does not provide an answer.').trim();
 r.explanation=s;
 r.importantPoints=['Explain the behavior and its trade-offs using the source example; distinguish Ruby language features from Rails extensions.'];
 const code=s.split('\n').filter(l=>/^\s*(?:def |class |module |end$|\w+ = |puts |print |p |require |gem |source |[\[\{]|\w+\.\w+|#|@\w|\w+\s*\|)/.test(l));
 r.example=code.length?code.join('\n'):'';
 if(/Rails|Active.?Record|migrat|Gemfile|Controller|rspec|RSpec/i.test(r.question))r.category='B';
 if(/garbage|metaprogram|singleton|thread|Fiber|monad|closure|ObjectSpace|memoiz|binding|pattern matching|internals/i.test(r.question))r.category='F';
 if(/N\+1|production|scalab|concurrent requests|optim|real-time/i.test(r.question))r.category='E';
 if(/\b(write|implement|find and|given an array|reverse|duplicate values)\b/i.test(r.question))r.category='D';
 if(r._key.startsWith('eight:Junior')||(/^nineteen:\d+$/.test(r._key)&&Number(r.sourceQuestionLabel)<=20)||r.sourceFile==='twentyone.txt')r.difficulty='Beginner';
 if(r._key.startsWith('eight:Expert')||(/^nineteen:\d+$/.test(r._key)&&Number(r.sourceQuestionLabel)>=41))r.difficulty='Advanced';
}
topic(/(?:What is Ruby(?: and|,| programming)|standout features|features of Ruby|advantages of using Ruby|Ruby and what makes|Everything is an Object|everything in Ruby is an object)/i,
 'Ruby is a dynamically typed, object-oriented language designed by Yukihiro Matsumoto. Its values are objects, and blocks, modules, open classes and readable syntax support expressive programs.',
 'Variables refer to objects and can later refer to objects of other classes; operations are checked at runtime. Classes are themselves objects, so Ruby can define behavior dynamically. CRuby normally compiles source to VM instructions before executing it; “interpreted” does not mean source is executed without any compilation. Rails is a separate web framework built with Ruby.',
 'p 7.class                 # Integer\np nil.to_s                # ""\np [1, 2, 3].select(&:even?) # [2]',
 ['Every Ruby value is an object; a block and language syntax are not independently objects.','Typing and execution strategy are different concepts.'], 'A','Beginner');
topic(/(?:variable types|types of variables|Ruby variables|What are variables|four types of variables|class variable and global|difference between local, instance, and class variables|Not Using Instance Variables)/i,
 'Ruby has local variables (name), instance variables (@name), class variables (@@name) and globals ($name). Constants begin with a capital letter and follow separate lookup rules.',
 'Locals belong to a lexical scope; blocks capture surrounding locals, while methods introduce their own local scope. Instance variables belong to the current object, including a class object when self is a class. Class variables are shared through a class hierarchy and can create surprising coupling; class instance variables often model per-class state more clearly. Globals are visible process-wide and should be used sparingly.',
 'class User\n  attr_reader :name\n  def initialize(name)\n    @name = name\n  end\nend\np User.new("Asha").name # "Asha"',
 ['Method visibility applies to methods, not to local-variable declarations.','An uninitialized instance variable reads as nil; an unknown local name can be parsed as a method call.'], 'A','Beginner');
topic(/(?:nil and false|nil, and what counts as false|Truthy and Falsy|nil, false, and empty)/i,
 'nil is the sole instance of NilClass and represents absence; false is the false Boolean value. Only nil and false are falsy in Ruby; 0, empty strings and empty collections are truthy.',
 'A conditional tests truthiness rather than calling empty?. An empty? query asks whether a supported container has no elements, and nil.empty? raises. nil is a normal Ruby value: it can be assigned, returned and stored in arrays or hashes. Use nil? to distinguish absence from a valid false result.',
 'p [nil, false, 0, "", []].map { |x| !!x } # [false, false, true, true, true]\np "".empty? # true',
 ['Do not treat a valid false setting as missing.','Rails blank? and present? are Active Support extensions.'], 'A','Beginner');
topic(/(?:symbol.*string|string.*symbol|Symbols vs\. Strings)/i,
 'Strings represent text and are normally mutable; symbols represent immutable names or identifiers. A symbol and a string with the same spelling remain different hash keys.',
 'Repeated occurrences of the same symbol refer to the same symbol object. String identity depends on allocation, freezing and runtime optimizations, so do not assume every literal always creates a different object. Dynamic symbols can be garbage-collected in modern CRuby. Prefer symbols for fixed API names and strings for external text; measure performance instead of claiming symbols are universally faster.',
 'h = { name: "Asha" }\np h[:name]  # "Asha"\np h["name"] # nil\np :name.to_s # "name"',
 ['Converting unbounded external input to identifiers can still consume memory.','Frozen string literals may share storage or identity.'], 'A','Beginner');
topic(/(?:require.*load|load.*require|require and require_relative|purpose of Ruby’s require)/i,
 'require loads a feature once and records it in $LOADED_FEATURES; load executes a file each time. require_relative resolves its path relative to the file containing the call.',
 'Use require for libraries and installed gems, and require_relative for a related project file when not using an autoloader. A successful new require returns true; a previously loaded feature normally returns false. load is deliberate re-execution, not the Rails autoloader. Prefer Rails’ configured autoloading conventions inside Rails applications.',
 'require "json"\nrequire_relative "support/formatter"\nload "./settings.rb"',
 ['require can raise LoadError.','Do not equate “load once” with loading exactly once under every possible alias or explicit manual modification.'], 'A','Beginner');
topic(/(?:access control|public, private, and protected)/i,
 'Ruby methods are public, protected or private. Public methods can be called normally; protected calls require a compatible caller context; private calls are internal and may use an implicit receiver or literal self in modern Ruby.',
 'Use private for implementation details. Protected methods let compatible instances cooperate, such as comparing balances without exposing them to arbitrary callers. Since Ruby 2.7, literal self.private_method is allowed; an arbitrary variable pointing to self does not gain that access. These are method call rules rather than a security boundary against introspection.',
 'class Account\n  def check = self.secret\n  private\n  def secret = 42\nend\np Account.new.check # 42\n# Account.new.secret raises NoMethodError',
 ['Older references stating “private never accepts explicit self” are outdated.','Reference: '+DOC+'syntax/modules_and_classes_rdoc.html'], 'A','Intermediate');
topic(/(?:difference between .*class.*module|modules and how.*differ|Ruby module\?|module mixins|modules and how do mixins)/i,
 'A class creates instances and may inherit from one superclass. A module groups constants and methods, provides a namespace and shares behavior through mixins; it cannot be instantiated as an ordinary instance or subclassed.',
 'Classes are themselves instances of Class, and Class inherits from Module. include places module instance methods in the receiving class’s ancestry, prepend places them before that class, and extend adds them to an object’s singleton class. Module composition supplies reusable behavior without multiple class inheritance.',
 'module Greetable\n  def greet = "hello"\nend\nclass User\n  include Greetable\nend\np User.new.greet # "hello"',
 ['Modules themselves are objects: Module.new creates a module, not an instance of that module.'], 'A','Intermediate');
topic(/(?:include.*extend|extend.*include)/i,
 'include adds a module’s instance methods to a class’s instances; extend adds them as singleton methods on the receiver. prepend inserts a module before the receiving class in method lookup.',
 'A class is also an object, so extending a class creates what are commonly called class methods. Extending an ordinary object affects just that object. With prepend, a wrapper can call super to continue into the original implementation. Examine ancestors or singleton_class.ancestors to see the actual lookup chain.',
 'module Greeting\n  def hello = "hello"\nend\nclass User\n  include Greeting\n  extend Greeting\nend\np User.hello\np User.new.hello',
 ['extend does not inherently mean “class only”: it works on ordinary objects too.','super follows the lookup chain, including mixins.'], 'A','Intermediate');
topic(/(?:proc and lambda|Proc and Lambda|blocks, procs, and lambdas|Block, Proc, and Lambda|Blocks, Procs, Lambdas|Procs And Blocks|blocks and procs)/i,
 'A block is code attached to a method call; a Proc object stores callable code. A lambda is a Proc with method-like argument checking and local return behavior, while an ordinary proc is lenient about positional arity and return exits its defining method.',
 'Use yield for the implicit block, &block to capture it, and call to execute a stored Proc. Both kinds close over surrounding local variables. A non-lambda proc with return can raise LocalJumpError if its defining method has already returned. A proc’s return target is where it was defined, not where it happens to be called.',
 'p ->(x) { x * 2 }.call(3) # 6\np proc { |x, y| [x, y] }.call(3) # [3, nil]\np ->(x) { x }.lambda? # true',
 ['Keyword argument rules still apply; “lenient arity” is not permission to pass every invalid call.','A method takes one implicit block but may receive many Proc objects as ordinary arguments.'], 'A','Intermediate');
topic(/(?:Ruby blocks|block differ from a method|What is a block and how|What are blocks in Ruby|Ruby Code Blocks)/i,
 'A block is an anonymous piece of code attached to a method call, written with braces or do/end. The method decides whether and when to run it, usually with yield.',
 'Blocks capture surrounding local variables and normally retain their defining self. They support iteration, callbacks and resource handling without defining a named method. Braces and do/end have different binding precedence; they are not always interchangeable in nested calls. Capture a block as a Proc with &block when you need to store or forward it.',
 'def twice\n  2.times { yield }\nend\ntwice { puts "hello" }',
 ['Calling yield without a supplied block raises LocalJumpError.'], 'A','Beginner');
topic(/(?:yield statement|yield and block_given|ampersand parameter)/i,
 'yield invokes the block passed to the current method, while block_given? reports whether that block exists. An &block parameter captures the block as a Proc, or nil when no block was supplied.',
 'Yield values to parameterize a caller’s behavior, such as an iterator yielding each record. Methods that offer optional callbacks should test block_given? or a captured block. At a call site, &callable turns a Proc or another object supporting to_proc into the method’s implicit block.',
 'def transform(x)\n  block_given? ? yield(x) : x\nend\np transform(4) { |n| n * n } # 16\np transform(4) # 4',
 ['The name block after & is conventional, not mandatory.'], 'A','Intermediate');
topic(/(?:\bsuper\b)/i,
 'super calls the next implementation of the current method in Ruby’s method lookup chain. Bare super forwards the current arguments; super() passes no positional or keyword arguments; super(args) passes the explicitly supplied arguments.',
 'This lets an override extend behavior supplied by a superclass or mixin instead of replacing it entirely. The next method must accept the forwarded arguments. Blocks are normally forwarded too; use &nil when you deliberately want to suppress the block. Ruby 3 separates positional hashes and keyword arguments, so forward both correctly when writing wrappers.',
 'class A\n  def greet(name = "guest") = "Hi #{name}"\nend\nclass B < A\n  def greet(name) = super + "!"\nend\np B.new.greet("Asha") # "Hi Asha!"',
 ['It calls the next lookup-chain method, which may be in a module rather than the immediate superclass.'], 'A','Intermediate');
topic(/(?:interpolation)/i,
 'String interpolation evaluates #{expression} inside a double-quoted or other interpolating string and inserts the result using to_s.',
 'Use interpolation for readable presentation of variables and expressions. Single-quoted strings preserve #{...} literally. Interpolation is not input escaping: embedding values directly in SQL, HTML or shell commands can introduce injection vulnerabilities, so use the appropriate parameterization or escaping mechanism for those contexts.',
 'name = "Asha"\np "Hello, #{name}: #{2 + 3}" # "Hello, Asha: 5"\np \'Hello, #{name}\' # literal characters',
 ['Interpolated nil becomes an empty string through nil.to_s.'], 'A','Beginner');
topic(/(?:==.*eql|eql.*hash|equality|operators and how.*==)/i,
 '== expresses class-specific value equality; equal? tests object identity; eql? together with hash determines Hash-key equality; === provides class-specific case matching.',
 'Integer distinguishes 1.eql?(1.0) from 1 == 1.0, but eql? is not a universal built-in “compare value and type” algorithm: classes define their own behavior. If two objects are eql?, they must return the same hash. A case/when clause effectively asks pattern === value, so Class, Range and Regexp give different matching meanings.',
 'p 1 == 1.0       # true\np 1.eql?(1.0)    # false\np (1..3) === 2   # true\ns = "a"; p s.equal?(s) # true',
 ['Never override equal? to implement ordinary value equality.','Keep key fields stable while an object is in a Hash.','Reference: '+DOC+'Object.html'], 'A','Intermediate');
topic(/(?:iterators|iterators like each)/i,
 'Ruby iterators call a block repeatedly. each performs side effects, map/collect builds transformed results, select/reject filters, reduce/inject accumulates and each_with_index supplies positions.',
 'Array#each normally returns the original array, while map returns a new array of block results. Enumerable methods supply common operations for classes defining each; sorting also needs a meaningful comparison. A missing block often returns an Enumerator, which can drive iteration externally with next. Lazy pipelines require Enumerator::Lazy rather than assuming every chained Enumerator operation is lazy.',
 'p [1, 2, 3].map { |n| n * 2 } # [2, 4, 6]\np [1, 2, 3].select(&:odd?) # [1, 3]\np [1, 2, 3].reduce(0, :+) # 6',
 ['Choose each for effects and map for returned values.','Repeated traversal and intermediate arrays can dominate performance.'], 'A','Beginner');
topic(/(?:Enumerator|enumerator objects)/i,
 'An Enumerator packages an iteration so it can be chained or driven with methods such as next. Create one from a method without a block or with Enumerator.new and a yielder.',
 'Enumerator.new can represent a custom or infinite producer. each drives it internally; next drives it externally and raises StopIteration when it is exhausted. Call lazy to build a demand-driven transformation pipeline; plain map on an Enumerator is generally eager. Lazy evaluation is especially useful when only a small prefix of a large or infinite source is needed.',
 'numbers = Enumerator.new { |y| n = 0; loop { y << n; n += 1 } }\np numbers.lazy.select(&:even?).take(3).force # [0, 2, 4]',
 ['Enumerator::Lazy prevents eager materialization of an unbounded source.'], 'A','Intermediate');
topic(/(?:inject|reduce)/i,
 'inject, also called reduce, combines a sequence into one accumulator using a block or named operation. An explicit initial value handles empty inputs predictably.',
 'The block receives the accumulator and current element, and its result becomes the next accumulator. Without an initial value, the first element initializes it; an empty collection then returns nil. If mutating a container accumulator, return that container or use each_with_object, whose block result is ignored.',
 'p [1, 2, 3].inject(0) { |sum, n| sum + n } # 6\np [].reduce(0, :+) # 0',
 ['inject is an alias of reduce.'], 'A','Beginner');
topic(/(?:garbage collection|garbage collector|Garbage Collection Feature)/i,
 'Ruby automatically reclaims unreachable objects. Modern CRuby uses a generational, incremental mark-and-sweep collector and supports compaction; this is an implementation detail rather than a guarantee for every Ruby runtime.',
 'The collector starts from roots and follows references, keeping reachable objects. Generational collection focuses frequent work on young objects; incremental work spreads some marking cost, and compaction can reduce fragmentation. Retained references in unbounded caches still grow memory even though the collector runs. Inspect GC.stat and profile allocations before tuning; collection does not guarantee process RSS immediately shrinks.',
 'before = GC.stat(:total_allocated_objects)\n100.times { Object.new }\np GC.stat(:total_allocated_objects) - before',
 ['“Unused” means unreachable, not merely no longer useful to the business.','Ruby does not generally use CPython-style reference counting.'], 'F','Advanced');
topic(/(?:method_missing)/i,
 'method_missing receives calls Ruby could not resolve normally. Override it only for a deliberate dynamic interface, implement respond_to_missing? consistently and delegate unhandled names to super.',
 'Known method names are usually clearer as actual methods, possibly generated using define_method. A dynamic proxy must validate the method name and argument shape, forward keywords and blocks correctly, and avoid accidentally swallowing typos. Introspection and Method lookup depend on respond_to_missing? reporting the same supported interface.',
 'class Settings\n  def initialize(data) = @data = data\n  def method_missing(name, *args, **kwargs, &block)\n    return @data[name] if args.empty? && kwargs.empty? && !block && @data.key?(name)\n    super\n  end\n  def respond_to_missing?(name, include_private = false)\n    @data.key?(name) || super\n  end\nend',
 ['Never recursively send every missing name back to itself.','Use an allowlist for external method names.'], 'F','Advanced');
topic(/(?:singleton methods|singleton class|class methods implemented|self methods)/i,
 'A singleton method belongs to one object and is stored in its singleton class. A class method is a singleton method of a class object; class << self opens that singleton class.',
 'Use singleton methods for behavior on a particular configurable object, and class methods for behavior associated with the class rather than one instance. Most ordinary objects can have singleton methods, but integers, floats and symbols cannot have arbitrary singleton classes in CRuby; nil, true and false have special cases. Not every use of self defines a class method: the value of self depends on context.',
 'obj = Object.new\ndef obj.greet = "hello"\np obj.greet\np obj.singleton_class\n# 5.singleton_class raises TypeError',
 ['Reference: '+DOC+'Object.html#method-i-singleton_class'], 'F','Advanced');
topic(/(?:self keyword|role of .self.|What does self refer)/i,
 'self is the current receiver. It is the instance inside an instance method, the class inside a class body or class method, and normally the defining context inside a block.',
 'Use self to distinguish a writer-method call from a local assignment: self.name = value invokes name=, while name = value defines a local. instance_eval and instance_exec can intentionally change self when running a block. Defining def self.build in a class body defines a singleton method on that class object.',
 'class User\n  attr_accessor :name\n  def rename(value)\n    self.name = value\n  end\nend',
 ['self is a receiver, not a reference to a statically determined class.'], 'A','Intermediate');
topic(/(?:define a method|Ruby methods|Normal Method Class|Implicit Returns)/i,
 'Define a method with def and call it on a receiver; Ruby returns the final evaluated expression unless return exits earlier. Methods can accept positional, keyword and block arguments.',
 'Use normal names such as snake_case for readability; Ruby also permits operator methods and other nonconventional names. A bare assignment creates a local variable, while a writer call needs an explicit receiver such as self.name = value. Ruby 3 separates keyword arguments from positional hashes, so wrappers should forward *args, **kwargs and &block or use ... where appropriate.',
 'def greet(name, punctuation: "!")\n  "Hello, #{name}#{punctuation}"\nend\np greet("Asha", punctuation: ".") # "Hello, Asha."',
 ['A method can return nil, false, a collection or any other Ruby value.'], 'A','Beginner');
topic(/(?:class and its constructor|create and use a class|create Ruby object|initialize method|implement inheritance)/i,
 'A class defines behavior for its instances. Class#new normally allocates an object and calls its initialize method; initialize sets state, while new returns the constructed object.',
 'Define instance methods in a class and expose state deliberately with accessors. A subclass declaration uses < to inherit from one superclass; overridden methods can call super to extend inherited behavior. initialize is a private instance method and is more precisely an initialization hook than the allocator itself.',
 'class User\n  attr_reader :name\n  def initialize(name)\n    @name = name\n  end\nend\np User.new("Asha").name # "Asha"',
 ['The return value of initialize is not the return value of the normal Class#new call.'], 'A','Beginner');
topic(/(?:metaprogramming|metaprogram|language of flexibility|flexible language)/i,
 'Metaprogramming lets Ruby programs define or inspect behavior at runtime, using tools such as define_method, singleton methods, reflection and module composition.',
 'Use metaprogramming for repetitive declarations and small DSLs when it makes the interface clearer. Prefer generating known methods with define_method over intercepting every call with method_missing. Open classes affect every user of a class, so consider a dedicated module or lexical refinement instead. Never eval untrusted strings or dispatch arbitrary external names through send.',
 'class Report\n  %i[csv json].each do |format|\n    define_method("export_#{format}") { "export as #{format}" }\n  end\nend\np Report.new.export_csv # "export as csv"',
 ['Ruby has no built-in numeric plus method; an example using plus must define it first.','Keep the dynamic interface discoverable with respond_to? and tests.'], 'F','Advanced');
topic(/(?:Ruby data types|basic data types|data types used in Ruby)/i,
 'Common Ruby value classes include Integer, Float, Rational, Complex, String, Symbol, Array, Hash, Range, Time, TrueClass, FalseClass and NilClass. All are object types.',
 'Dynamic typing means a variable can reference different classes over time; it does not mean Ruby silently accepts incompatible operations. Ruby presents no separate nonobject primitive type hierarchy to application code, even though CRuby uses efficient immediate internal representations for some values. Integers grow subject to available memory; Float uses finite precision.',
 'p [42, 3.5, "hi", :name, [], {}, nil].map(&:class)',
 ['"5" + 2 raises TypeError; use an intentional conversion such as Integer("5").'], 'A','Beginner');
topic(/(?:freeze an object|What does freeze|freeze.*frozen_string_literal)/i,
 'freeze prevents mutation of an object itself and returns that object. It is shallow: referenced nested objects can remain mutable, and the variable or constant can still be rebound.',
 'The frozen_string_literal magic comment controls eligible string literals in its source file. Mutation attempts normally raise FrozenError. Freezing a constant’s value does not prohibit assigning that constant a new value; Ruby typically warns on reassignment. Deep immutability requires freezing or otherwise protecting nested values too.',
 'items = ["a"].freeze\n# items << "b" raises FrozenError\nitems.first << "!" # nested String remains mutable\np items # ["a!"]',
 ['dup normally produces an unfrozen shallow copy; clone normally retains frozen state.'], 'A','Intermediate');
topic(/(?:Duck Typing|duck typing)/i,
 'Duck typing means code depends on an object’s supported behavior rather than requiring a particular class. Any object implementing the required protocol can collaborate.',
 'For example, code accepting a writer only needs write, not a concrete File class. This makes testing easier because a StringIO or test double can satisfy the same interface. respond_to? can check availability, but shared semantics and error behavior matter as well; a matching method name alone does not prove compatibility.',
 'require "stringio"\ndef log(writer, message)\n  writer.write(message + "\\n")\nend\nbuffer = StringIO.new\nlog(buffer, "ready")\np buffer.string # "ready\\n"',
 ['Prefer a small documented protocol over broad concrete-class checks.'], 'A','Intermediate');
topic(/(?:Rails Migration|purpose of migrations|create.*migration|migration command|Command To Create A Migration|rails db:migrate)/i,
 'A Rails migration is a versioned Ruby description of database changes. Generate it with bin/rails generate migration and apply pending changes with bin/rails db:migrate.',
 'Migrations evolve schema consistently across environments; reversible operations can use change, while operations that Rails cannot reverse need reversible or explicit up/down methods. Data backfills and index creation on large live tables need deployment planning; database portability is not automatic for every SQL operation or index feature.',
 'bin/rails generate migration AddStatusToUsers status:string\nbin/rails db:migrate\nbin/rails db:rollback',
 ['ruby script/generate is a historical Rails command.','Reference: https://guides.rubyonrails.org/active_record_migrations.html'], 'B','Intermediate');
topic(/(?:What is Rails\?|What Is Rails|What is Ruby on Rails\?|Rails structure an application|MVC|Model View Controller)/i,
 'Rails is a Ruby web framework following Model–View–Controller and convention over configuration. Models represent domain behavior, controllers handle HTTP requests, and views present responses.',
 'Active Record supplies database mapping for models that use it; domain models need not all inherit from Active Record. Routing selects a controller action based on both path and HTTP method. Controllers coordinate work and render HTML, JSON or other responses, while keeping substantial business rules in reusable model or application-service code.',
 '# config/routes.rb\nresources :articles, only: [:index, :show]\n# GET /articles/5 routes to ArticlesController#show',
 ['MVC separates responsibilities but does not prescribe that every rule lives in a single Active Record class.'], 'B','Beginner');
topic(/(?:Active.?Record.*(?:Rails|used)|What is Active Record)/i,
 'Active Record is Rails’ object-relational mapping layer, exposing database rows through Ruby objects and query relations, with associations, validations and callbacks.',
 'A model typically maps to a table by naming convention; objects represent rows and columns become attributes. Relations compose and usually execute lazily. Model validations help user-facing correctness, but database constraints are needed for integrity under concurrent requests. Query methods still generate SQL and can be inefficient or unsafe if raw interpolated fragments are supplied.',
 'class User < ApplicationRecord\n  has_many :posts\n  validates :email, presence: true\nend\nUser.where(active: true).order(:id).limit(20)',
 ['Active Record is a Rails component, not part of Ruby core.'], 'B','Intermediate');
topic(/(?:Rails Controller|Rails controller)/i,
 'A Rails controller receives a routed request, checks request-level concerns, coordinates domain work and returns an HTTP response such as HTML or JSON.',
 'Actions read permitted parameters, scope database access to the current user or tenant, invoke application behavior and render or redirect. Keep authentication and authorization distinct. Request state belongs to a controller instance, while long-lived shared caches and class state need concurrency care.',
 'class PostsController < ApplicationController\n  def show\n    post = current_user.posts.find(params[:id])\n    render json: { id: post.id, title: post.title }\n  end\nend',
 ['A serializer or explicit field list prevents unintended data exposure.'], 'B','Beginner');
topic(/(?:N\+1|eager loading)/i,
 'An N+1 query loads a collection and then performs another query per record for an association. Preload the needed associations with includes, preload or eager_load and verify the actual SQL.',
 'preload normally issues separate queries for associations, while eager_load uses a LEFT OUTER JOIN. includes chooses behavior according to the relation, so it does not guarantee a single query. Avoid loading huge associated collections blindly; select needed data, paginate and compare query counts, query plans and memory.',
 'Post.includes(:author).limit(20).each { |post| puts post.author.name }',
 ['A query count improvement can increase transferred rows or object allocations; measure both.','Reference: https://guides.rubyonrails.org/active_record_querying.html#eager-loading-associations'], 'E','Intermediate');
topic(/(?:background jobs)/i,
 'Background jobs move work outside the request-response cycle. Use Rails Active Job with an appropriate backend, or a backend-specific interface such as Sidekiq when its features are needed.',
 'Jobs need idempotent behavior because retries or redelivery may repeat work. Pass durable identifiers, set retry policies and timeouts, monitor queue lag and failures, and coordinate enqueueing with database commit. Sidekiq uses Redis and threads; Solid Queue is a database-backed Rails option. Choose according to workload and operational needs rather than assuming one default for every Rails version.',
 'class ReportJob < ApplicationJob\n  def perform(report_id)\n    report = Report.find(report_id)\n    report.generate_once!\n  end\nend\nReportJob.perform_later(report.id)',
 ['A queue does not by itself provide exactly-once business effects.'], 'B','Intermediate');
topic(/(?:security attacks|security best practices|implement security measures)/i,
 'Use layered Rails defenses: authenticate users, authorize every resource access, permit mass-assignment fields, bind SQL parameters, escape output, protect cookie-authenticated requests from CSRF and keep dependencies patched.',
 'Strong parameters limit assignment but do not grant authorization. Parameterized Active Record conditions separate SQL structure from values; input validation alone is not SQL-injection protection. Rails escapes ordinary rendered text, but raw/html_safe and unsafe HTML contexts can reintroduce XSS. Use HTTPS and secure cookie settings, reset sessions appropriately at authentication boundaries, filter secrets from logs, and make password storage an established hashing implementation.',
 'user = current_account.users.find(params[:id])\nallowed = params.require(:user).permit(:name)\nuser.update!(allowed)\n# Binding values, not SQL interpolation:\nUser.where(email: params[:email])',
 ['CSRF tokens protect applicable cookie-authenticated workflows; they do not prove consent or prevent XSS.','Reference: https://guides.rubyonrails.org/security.html'], 'B','Intermediate');
topic(/(?:rake task)/i,
 'Rake automates named tasks with dependencies. In Rails put a .rake file in lib/tasks and depend on :environment when the task needs application models.',
 'Use namespaces and descriptions for discoverability. Commands such as bin/rails data:cleanup execute the task in the application context. For production tasks, plan batching, observability, idempotency and dry-run behavior where useful; a task file is not automatically safe to rerun.',
 '# lib/tasks/reports.rake\nnamespace :reports do\n  desc "Show the report count"\n  task count: :environment do\n    puts Report.count\n  end\nend\n# bin/rails reports:count',
 ['A non-Rails Rakefile can define standalone tasks without :environment.'], 'B','Intermediate');
topic(/(?:Gemfile|manage dependencies|What is a Gem|What are Gems|gems and how does Bundler)/i,
 'A gem packages Ruby code and metadata. Bundler resolves dependencies declared in a Gemfile and records selected versions in Gemfile.lock; bundle exec selects that bundle when running a command.',
 'Declare direct dependencies and constraints intentionally, install with bundle install and update selected dependencies with testing. Commit the application lockfile for reproducible development and CI installations. RubyGems supplies gem installation and distribution, while Bundler selects a consistent dependency set for a project; a gem need not be installed globally or published publicly.',
 '# Gemfile\nsource "https://rubygems.org"\ngem "rack"\n# shell: bundle install\n# shell: bundle exec ruby app.rb',
 ['Example version pins in old articles are historical, not current upgrade recommendations.'], 'A','Intermediate');
topic(/(?:RSpec framework|tests in Ruby with RSpec|support testing)/i,
 'RSpec and Minitest are Ruby test frameworks. Rails integrates Minitest by default; RSpec is an optional dependency, commonly integrated through rspec-rails.',
 'Write examples around observable behavior and important failures, and use appropriate unit, request, integration and system tests. Isolate nondeterministic dependencies such as network calls and time while preserving meaningful database integration checks. RSpec describe/context group behavior and expect expresses outcomes; Minitest uses assertions or its spec interface.',
 'RSpec.describe "integer addition" do\n  it "adds values" do\n    expect(2 + 3).to eq(5)\n  end\nend',
 ['RSpec is not a built-in part of Rails.','Distribution of Minitest as a bundled gem depends on Ruby version; declare test dependencies explicitly.'], 'B','Intermediate');
topic(/(?:getter and setter|accessor methods|attr_accessor, attr_reader, and attr_writer)/i,
 'attr_reader defines a getter, attr_writer defines a setter and attr_accessor defines both for an instance variable. They generate methods, not database columns or validations.',
 'Use the least writable interface needed by callers. A reader-only attribute does not recursively freeze its returned value, and methods can be defined manually when writes need validation or normalization. Declaring both reader and writer has the same basic accessor effect as attr_accessor, so assignments succeed when both are present.',
 'class Person\n  attr_accessor :name\n  def initialize(name) = @name = name\nend\nperson = Person.new("Asha")\nperson.name = "Ben"\np person.name # "Ben"',
 ['Do not confuse accessors with Rails persistence: an arbitrary attr_accessor is transient unless application code persists it.'], 'A','Beginner');
topic(/(?:case statement|case\/when actually|case.*===)/i,
 'case/when evaluates patterns using pattern === target and runs the first matching branch. If nothing matches it runs else, or returns nil when else is absent.',
 'Classes use === for instance membership, ranges for interval coverage, and regular expressions for matching. A case with no target instead tests branch truthiness. case is an expression, so it can return the selected branch’s result. case/in is a separate destructuring form with additional pattern rules.',
 'case value\nwhen Integer then "number"\nwhen /\\A[a-z]+\\z/ then "letters"\nelse "other"\nend',
 ['Branch order matters: a broad class match can make a later narrower range branch unreachable.'], 'A','Intermediate');
topic(/(?:array\.map\(&|&:method|&:method_name)/i,
 'At a call site, & converts an object to a block using to_proc. Symbol#to_proc produces callable behavior that invokes the named method on each supplied receiver.',
 'Thus array.map(&:upcase) behaves like array.map { |item| item.upcase } for this simple transform. This shorthand is appropriate when the block is exactly one such call; use a normal block for additional logic, multiple yielded values or clearer parameter handling.',
 'p ["a", "b"].map(&:upcase) # ["A", "B"]\np ["a", "b"].map { |s| s.upcase }',
 ['The ampersand is block conversion here, not bitwise AND.'], 'A','Intermediate');
// Specific records retain their original source but get corrected, interview-ready explanations.
set('nine:2','Ruby was designed by Yukihiro Matsumoto, usually called Matz, and first publicly released in 1995.','The source misspells his nickname as “Martz”. The language was designed in Japan; historical naming anecdotes are less useful in an interview than explaining the design goals.','p RUBY_DESCRIPTION',['Ruby’s creator and the language’s release date are separate facts.'],['Corrected creator nickname from Martz to Matz.']);
set('eight:Junior-06','The shown greet method is valid Ruby. It prints a greeting and returns nil because puts returns nil.','There is no syntax error to fix. If the requirement is to return the greeting for another caller to use, remove puts and leave the interpolated string as the final expression. Printing and returning are different requirements.','def greet(name)\n  "Hello, #{name}"\nend\np greet("Alice")',['Do not invent a bug when the input is already valid.'],['Source answer contradicts itself about whether puts should be used. Corrected to distinguish printing from returning.']);
set('eight:Mid-03','It prints Hello Woof! followed by a newline.','Dog#speak calls the next speak implementation using super. Animal#speak returns "Hello"; concatenating " Woof!" produces the string printed by puts. The final puts itself returns nil.','p Dog.new.speak # assuming the classes in the source are defined: "Hello Woof!"',['super continues method lookup; + builds a String value.']);
set('eight:Expert-03','user.name = "Bob" fails because attr_reader defines only name, not name=. Add attr_writer or use attr_accessor if mutation is part of the class contract.','A reader method can expose state while keeping writes private to the object. If public renaming is intended, explicitly expose a writer; if the object should be immutable, remove the attempted assignment.','class User\n  attr_accessor :name\n  def initialize(name) = @name = name\nend\nuser = User.new("Alice")\nuser.name = "Bob"',['Changing the accessor is a design decision, not merely a syntax repair.']);
set('eight:Expert-02','ObjectSpace provides runtime object enumeration and diagnostic facilities. Additional heap and memory-size methods are available after requiring objspace.','Use it to investigate retained objects, counts and allocation behavior, often alongside GC.stat. Heap inspection can be expensive and some capabilities are CRuby-specific. Object IDs are diagnostic identities, not durable keys or a safe ownership model.','require "objspace"\np ObjectSpace.count_objects\np ObjectSpace.memsize_of("hello")',['ObjectSpace.dump_all is supplied by the objspace extension.','Reference: '+DOC+'ObjectSpace.html'],['Source omitted require "objspace" for extended ObjectSpace inspection methods.']);
set('eight:Expert-04','Fibers are lightweight cooperative execution contexts within a thread; threads are scheduled independently by the runtime and operating system.','A fiber normally yields or suspends at controlled points. A Fiber scheduler can make supported blocking operations cooperative, which enables high concurrency for I/O. Fibers do not automatically provide CPU parallelism. In CRuby the global VM lock limits ordinary Ruby-thread CPU parallelism; other runtimes differ.','fiber = Fiber.new { Fiber.yield :paused; :done }\np fiber.resume # :paused\np fiber.resume # :done',['Fiber.yield and puts have different return values.','The source comments showing printed text as resume’s return value are misleading.'],['Clarified output versus Fiber#resume return values and scheduler behavior.']);
set('eight:Expert-05','A monad is a type supporting a unit operation and a composition operation such as bind, subject to identity and associativity laws. Ruby libraries use such abstractions for optional values and success/failure pipelines.','The source’s Maybe wrapper is a useful sketch: bind skips work for nil and otherwise passes the value to the next computation. It should require the block to return a compatible wrapper, supply constructors for presence/absence and test the monad laws before claiming a full lawful abstraction. This is a design abstraction, not a built-in Ruby language feature.','class Maybe\n  def self.unit(value) = new(value)\n  def initialize(value) = @value = value\n  def bind\n    @value.nil? ? self : yield(@value)\n  end\nend\nresult = Maybe.unit(10).bind { |x| Maybe.unit(x * 2) }',['Distinguish a formal monad from an arbitrary chainable wrapper.'],['Source loosely equates monads with a design pattern and side effects; added the operation/law requirement.']);
set('nine:13','In modern Ruby retry is valid in a rescue clause and restarts the corresponding begin body; it does not restart an arbitrary loop.','Track an attempt limit and retry only failures expected to be transient. Retrying an operation with external effects requires idempotency or a rollback strategy. Use redo to repeat the current loop iteration without rechecking the condition.','attempts = 0\nbegin\n  attempts += 1\n  raise "transient" if attempts < 2\nrescue RuntimeError\n  retry if attempts < 3\n  raise\nend',['Reference: '+DOC+'syntax/exceptions_rdoc.html'],['Corrected obsolete/wrong claim that retry restarts a whole loop.']);
set('nine:46',find('nine:13').directAnswer,find('nine:13').explanation,find('nine:13').example,find('nine:13').importantPoints,['Source syntax example was missing; supplied a bounded retry illustration.']);
set('nine:18','Ruby blocks use { ... } or do ... end, but their binding precedence differs.','Braces bind more tightly than do/end in method-call parsing. Use braces conventionally for short expressions and do/end for longer blocks, but do not mechanically swap them in nested calls.','[1, 2, 3].each { |n| puts n }\n[1, 2, 3].each do |n|\n  puts n\nend',['Parentheses can make the target method unambiguous.'],['Corrected claim that both syntaxes always have identical functionality.']);
set('nine:28','Compare String values with == or eql?, order them with <=>, or use casecmp/casecmp? for case-insensitive comparison.','casecmp returns a negative integer, zero, a positive integer or nil when comparison is not possible; it does not just return zero or one. casecmp? returns a Boolean or nil in unsupported cases. Decide whether binary, encoding-aware or domain-specific normalization is required.','p "a" <=> "b"   # -1\np "Ruby".casecmp("ruby") # 0\np "Ruby".casecmp?("ruby") # true',['Unicode and locale-sensitive comparison may need explicit normalization.'],['Corrected casecmp return-value claim.']);
set('nine:34','Time.now or Time.new with no arguments returns the current time. Time.new(year, month, day, ...) constructs a specified calendar time.','When components are supplied, defaults apply to omitted fields according to the method signature. Time zones and offsets should be explicit when converting between user-facing wall times and stored instants. A year is not required for the no-argument current-time constructor.','p Time.now\np Time.new(2026, 1, 1, 0, 0, 0, "+05:30")',['Time and Date serve different use cases.'],['Corrected contradictory claim that Time.new always requires a year.']);
set('nine:39','Use gets for one line, read for the remaining contents, and readlines for an array of remaining lines; File.foreach streams lines without loading the entire file.','The methods read from the current file position. Prefer a block-based open or File.foreach so the descriptor is closed even if an exception occurs. Whole-file reads require memory proportional to input size.','File.open("input.txt", "r") do |f|\n  first = f.gets\n  rest = f.read\nend\nFile.foreach("input.txt") { |line| puts line }',['The source typo f.rea should be f.read.'],['Corrected truncated method name and missing closure in examples.']);
set('nine:40','IO#sysread(length) performs a low-level read of up to a requested number of bytes from an already readable IO object.','It requires a length argument, may raise EOFError at end of input and should not be mixed carelessly with buffered read methods on the same stream. It does not open a file or make a write-only stream readable. Prefer normal buffered read for ordinary application work.','File.open("input.txt", "rb") do |file|\n  p file.sysread(8)\nrescue EOFError\n  puts "empty file"\nend',['Use binmode when processing raw bytes.'],['Corrected claim that sysread opens a file in any mode.']);
set('nine:42','Use Dir.exist?(path) to check whether a path names an existing directory.','The old plural exists? aliases were deprecated and removed in modern Ruby. A prior existence check can race with subsequent operations, so operations that must succeed should also handle their actual filesystem errors.','p Dir.exist?(".") # true',['Reference: '+DOC+'Dir.html'],['Replaced removed Dir.exists? with Dir.exist?.']);
set('nine:49','The source omits the code that defines val1 and val2, so their exact values cannot be verified from this file alone.','The included explanation is about operator precedence: and/or bind less tightly than assignment, whereas &&/|| bind more tightly. The following is an illustrative reconstruction, not recovered source code.','val1 = true and false\nval2 = true && false\np [val1, val2] # [true, false]',['Do not claim an output for absent code.'],['Incomplete source: referenced val1/val2 code is absent.']);
set('nine:51','The referenced method definitions and call list are missing, so the full output cannot be determined.','The retained explanation identifies a real parsing trap: sum(1, 2) passes two arguments, whereas a space before parentheses may make Ruby parse one parenthesized expression. The comma expression in sum (1, 2) is invalid. The claimed 10/3 outputs need the missing method definitions to be independently checked.','def sum(a, b) = a + b\np sum(1, 2) # 3\n# sum (1, 2) # SyntaxError',['Method-call style recommendations are conventions, but parse errors are language behavior.'],['Incomplete source: missing definitions and original call list.']);
set('nine:52','The exact one-liner is absent, but the explanation describes an immediately invoked lambda that prints an inspected String.','A stabby lambda ->(a) { p a } is a Proc with lambda semantics. It can be invoked with call or [] syntax. p writes inspect and returns its argument; it differs from puts, which returns nil. The example below is a reconstruction for explanation.','->(a) { p a }["Hello World"] # prints "Hello World" with quotes',['All lambdas are Proc objects, but not all Proc objects have lambda behavior.'],['Incomplete source: referenced code line is missing; example explicitly reconstructed.']);
set('nine:56','Build the requested number of Fibonacci values while carrying the latest pair, and print the resulting array.','The source expression appends twenty numbers to an initial two-element array, so it returns twenty-two terms rather than twenty. Define F(0)=0, F(1)=1 and a nonnegative requested length. The example handles zero length correctly and runs in O(n) arithmetic steps plus O(n) output space.','n = 20; p Array.new(n).each_with_object([0, 1]) { |_, fib| fib << fib[-1] + fib[-2] }.first(n)',['Integer arithmetic cost grows with very large Fibonacci values.'],['Clarified the source expression’s output-length off-by-two behavior.']);
set('nine:58','A gem is a Ruby package. A plugin is an extension role or integration mechanism; modern Rails plugins are commonly packaged as gems, often with a Railtie or engine.','The source describes an older distinction between machine-installed gems and application-local vendor/plugins. Modern Bundler can install gems per project, and plugins can be distributed as gems, so installation location does not define the difference.','bin/rails plugin new audit_tools\n# Include the resulting package in an application through its Gemfile.',['Distinguish historical Rails plugin layout from current packaging.'],['Corrected outdated gem-versus-plugin location rule.']);
set('nine:60','The intended names are Float, Float::DIG and Float::MAX. Float is Ruby’s floating-point numeric class; DIG describes guaranteed decimal precision, and MAX is the largest finite representable Float.','Float values use a finite binary representation, so many decimal fractions are inexact. These constants describe representation limits rather than tasks called “dig” and “max”. Do not confuse Float::DIG with Hash#dig, or Float::MAX with an arbitrary-precision integer limit.','p Float::DIG\np Float::MAX\np 0.1 + 0.2 == 0.3 # false on usual IEEE-754 runtimes',['Use BigDecimal for domain needs requiring decimal arithmetic.','Reference: '+DOC+'Float.html'],['Corrected nonsensical Float/Dig/Max descriptions and capitalization.']);
set('nine:65','Ruby Integer supports arbitrarily large integer values subject to available memory and computation cost.','Since Ruby 2.4, Fixnum and Bignum were unified under Integer. CRuby may still use different internal representations for small and large integers, but applications should use Integer rather than branching on the old class names. Large-number operations have growing time and memory costs.','p (2 ** 100).class # Integer\np 2 ** 100',['“Arbitrary precision” does not mean unlimited physical resources.'],['Updated historical Fixnum/Bignum class explanation.']);
set('nine:68','The prompt “Normal Method Class” is ambiguous; the source appears to discuss Ruby method invocation and argument forwarding.','A regular method call may receive positional arguments, keyword arguments and a block. At the call site * expands a positional array, ** expands keyword pairs and & passes a block. Modern Ruby separates a trailing positional hash from keywords when the callee declares keyword parameters. :: can call methods, but . is the normal readable form.','def total(*values, multiplier: 1)\n  values.sum * multiplier\nend\np total(*[2, 3], multiplier: 2) # 10',['The source does not define a formal concept named “normal method class”.'],['Incomplete/ambiguous question wording retained; explained only the identifiable method-call content.']);
set('nine:69','Common Ruby command-line options include -e for an expression, -r to require a library, -I to add a load path, -w for warnings, -c for syntax checking and -v for version information.','Use ruby --help for the exact runtime’s flags. Historical options such as taint-related -T belong to removed Ruby security mechanisms and should not be recommended in modern Ruby. ARGV contains remaining script arguments.','ruby -v\nruby -c app.rb\nruby -rjson -e \'puts JSON.generate({ok: true})\'',['Reference: https://docs.ruby-lang.org/en/3.4/ruby/options_md.html'],['Flagged removed taint/safe-level option -T in old source.']);
set('nine:83','Ruby follows the receiver’s method lookup chain, including singleton-class ancestry, prepended modules, its class, included modules and superclasses. If resolution fails it invokes method_missing.','Within each ancestry segment, prepend appears before the owning class and include after it. super resumes after the currently executing implementation. Active refinements can also affect lookup. The default missing-method behavior raises NoMethodError, a NameError subclass.','module A; def hello = "A"; end\nclass User; include A; end\np User.ancestors\np User.new.hello',['The hook is method_missing, not method_missing?.','Reference: '+DOC+'syntax/calling_methods_rdoc.html'],['Corrected nonexistent method_missing? name and oversimplified lookup order.']);
set('nine:84','The source lacks the original class, but its explanation identifies a local assignment used where a setter call was intended. Use self.address = a to invoke address=, or assign an intentionally normalized value to @address.','An unqualified address = a is parsed as local-variable assignment and does not call an accessor. Choosing @address = a bypasses any writer normalization or validation, so it is equivalent only when that is intended. The missing clean method cannot be assumed to exist.','class User\n  attr_reader :address\n  def address=(value) = @address = value.strip\n  def initialize(value)\n    self.address = value\n  end\nend',['Reconstruction illustrates the bug; it is not the absent original class.'],['Incomplete source: original code is absent.']);
set('nine:86','After replacing typographic quotes with Ruby string delimiters, the lambda prints the inspected String "I’m a Proc".','The [] call invokes the lambda. p returns the printed String, so the expression’s result is that String rather than nil. As pasted, the curly opening and closing quote characters are not valid ordinary Ruby string delimiters.','->(s) { p s }["I’m a Proc"]',['p prints quotes around a String; puts normally does not.'],['Corrected pasted typographic quote delimiters and clarified inspected output.']);
set('nine:87','False (option b): upcase uppercases the full string; capitalize uppercases the first character and lowercases the remainder.','The exact effect follows Ruby’s Unicode casing rules and options. Both methods return a new String; their bang variants mutate the receiver and may return nil when nothing changes.','p "hELLO wORLD".upcase # "HELLO WORLD"\np "hELLO wORLD".capitalize # "Hello world"',['capitalize also lowercases the rest; it does not merely preserve all following characters.'],['Added missing lowercase-rest behavior.']);
set('nine:88',find('nine:87').directAnswer.replace('False (option b): ','Option b is closest, with an important qualification: '),find('nine:87').explanation,find('nine:87').example,find('nine:87').importantPoints,['Source simplification omitted lowercasing the remaining characters.']);
set('nine:89','The class A and method a are absent, so the stated nil and 4 outputs cannot be established from the source alone.','A plausible teaching example is a method whose final expression is an if without else, returning the square for a positive input and nil otherwise. But many other implementations are possible; do not present that reconstruction as the supplied original.','class A\n  def self.a(x)\n    x * x if x > 0\n  end\nend\np [A.a(0), A.a(2)] # [nil, 4], for this reconstruction only',['if expressions without a matching branch or else return nil.'],['Incomplete source: defining class/method is missing.']);
set('nine:90','Array#each yields elements and normally returns the original array; Array#map returns a new array containing each block result. collect is an alias of map.','Neither method intrinsically guarantees the source’s contents remain unchanged: the block can mutate elements or shared state. map! replaces array elements in place. Use each for effects and map when its resulting collection is needed.','a = [1, 2]\np a.each { |n| n * 2 } # [1, 2]\np a.map { |n| n * 2 } # [2, 4]',['A map block calling puts produces nil entries.'],['Qualified source’s claim that each/map leave the original unaffected regardless of block behavior.']);
set('nine:92','All four forms can invoke xyz on a newly constructed ABC instance, assuming ABC.new and xyz exist. Their return value depends on xyz.','Ruby permits :: for a method receiver in these forms as well as for namespaces, but . is the conventional method-call syntax and avoids ambiguity. The source omits ABC’s definition, so no concrete return value can be asserted.','class ABC\n  def xyz = 42\nend\np ABC.new.xyz # 42',['Syntactic validity and a specific return value are separate questions.'],['Incomplete source: ABC/xyz implementation is missing.']);
set('nine:93','upcased is [nil, nil, nil], while ONE, TWO and THREE are printed on separate lines.','map stores each block’s final value. Here that value comes from puts, which returns nil. If the array of uppercase strings is wanted, use map(&:upcase) without printing as the final operation.','upcased = ["one", "two", "three"].map { |n| puts n.upcase }\np upcased # [nil, nil, nil]',['Keep returned values separate from console side effects.']);
set('nine:94','The preceding definitions of foo and bar are missing, so the exact defined? results cannot be determined.','defined? examines whether an expression is recognized without ordinarily evaluating it and returns a descriptive String or nil. Merely reading an unknown identifier does not universally initialize a local to nil; parser-visible assignment can establish a local even when the assignment branch is not executed.','foo = 1 if false\np defined?(foo) # "local-variable"\np foo           # nil\np defined?(bar) # nil, if no such local/method exists',['Results depend on scope and available methods.'],['Incomplete source and inaccurate explanation: missing prior code; reading alone does not define a local.']);
set('nine:95','dup and clone both make shallow copies; clone normally preserves singleton-class behavior and frozen state, while dup normally does not copy singleton methods and returns an unfrozen copy.','Nested references are shared unless application code deep-copies them. Included modules on the ordinary class remain available to both copies because their class still has them; the relevant distinction is per-object singleton-class behavior, such as object.extend(module). Some immutable immediate values cannot be copied into a distinct mutable object.','obj = Object.new\ndef obj.greet = "hi"\nobj.freeze\np obj.clone.frozen? # true\np obj.dup.frozen?   # false\np obj.clone.respond_to?(:greet) # true',['Reference: '+DOC+'Object.html'],['Clarified instance-level extensions versus modules mixed into the ordinary class.']);
set('nine:98','A closure is executable code together with access to the local environment in which it was created. Ruby blocks, procs and lambdas capture surrounding locals and can outlive the defining call.','Captured variables remain shared references, so changing a captured local is visible to the closure and can keep associated objects alive. Proc#binding exposes its execution context but does not arbitrarily replace the closure’s environment. Use closures for callbacks, stateful generators and small configurable behavior.','def counter\n  n = 0\n  -> { n += 1 }\nend\nc = counter\np [c.call, c.call] # [1, 2]',['Avoid unintended retention of a large surrounding object graph.'],['Corrected suggestion that #binding simply alters a closure’s binding.']);
// Per-record issues ensure questionable original claims remain visibly separated from corrected guidance.
const addIssue=(key,note)=>find(key).issues.push(note);
for(const key of ['seven:2','nine:75','nine:78','nineteen:27'])addIssue(key,'Updated private-method receiver rule: literal self is permitted in Ruby 2.7+; older blanket prohibition is outdated.');
for(const key of ['seven:3','eight:Junior-01','nineteen:3','twentyfour:4'])addIssue(key,'Qualified absolute identity/performance claims: frozen strings may be shared; dynamic symbols can be collected; symbols are not universally faster.');
